import json
import time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from email.utils import parsedate_to_datetime
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = \"http://localhost:8080\"
token = None
request_count = 0
retry_count = 0
token_refreshes = 0

def retry_delay(headers, attempt):
    value = headers.get(\"Retry-After\") if headers else None
    if value:
        try:
            return max(0.0, float(value))
        except ValueError:
            try:
                when = parsedate_to_datetime(value)
                if when.tzinfo is None:
                    when = when.replace(tzinfo=timezone.utc)
                return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())
            except Exception:
                pass
    return min(2 ** min(attempt, 5), 30)

def fetch_token():
    global token_refreshes, retry_count
    attempt = 0
    while True:
        try:
            req = Request(BASE + \"/token\", method=\"POST\")
            with urlopen(req, timeout=30) as resp:
                body = json.load(resp)
            tok = body.get(\"token\")
            if not isinstance(tok, str) or not tok:
                raise RuntimeError(\"token endpoint returned no usable token\")
            token_refreshes += 1
            return tok
        except HTTPError as exc:
            if exc.code == 429 or 500 <= exc.code < 600:
                retry_count += 1
                delay = retry_delay(exc.headers, attempt)
                time.sleep(delay)
                attempt += 1
                continue
            raise
        except (URLError, TimeoutError):
            retry_count += 1
            time.sleep(min(2 ** min(attempt, 5), 30))
            attempt += 1

def get_json(path):
    global token, request_count, retry_count
    attempt = 0
    while True:
        if token is None:
            token = [REDACTED_SECRET]
        req = Request(BASE + path, headers={\"Authorization\": \"Bearer \" + token})
        try:
            request_count += 1
            with urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except HTTPError as exc:
            if exc.code == 401:
                token = None
                retry_count += 1
                attempt += 1
                continue
            if exc.code == 429 or 500 <= exc.code < 600:
                retry_count += 1
                delay = retry_delay(exc.headers, attempt)
                time.sleep(delay)
                attempt += 1
                continue
            raise
        except (URLError, TimeoutError):
            retry_count += 1
            time.sleep(min(2 ** min(attempt, 5), 30))
            attempt += 1

orders_by_id = {}
duplicates_skipped = 0
conflicting_duplicates = []
pages_fetched = 0
path = \"/orders?page=1\"
seen_paths = set()
reported_total_pages = None

while path is not None:
    if path in seen_paths:
        raise RuntimeError(f\"pagination loop detected at {path}\")
    seen_paths.add(path)
    page = get_json(path)
    pages_fetched += 1
    if reported_total_pages is None:
        reported_total_pages = page[\"total_pages\"]
    elif page[\"total_pages\"] "'!= reported_total_pages:
        raise RuntimeError("total_pages changed during pagination")
    for order in page["items"]:
        oid = order["id"]
        if oid in orders_by_id:
            duplicates_skipped += 1
            if order != orders_by_id[oid]:
                conflicting_duplicates.append(oid)
        else:
            orders_by_id[oid] = order
    path = page["next"]

if pages_fetched != reported_total_pages:
    raise RuntimeError(f"fetched {pages_fetched} pages but API reported {reported_total_pages}")

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in orders_by_id.values():
    raw = order["placed_at"]
    parsed = datetime.fromisoformat(raw[:-1] + "+00:00" if raw.endswith("Z") else raw)
    if parsed.tzinfo is None:
        raise RuntimeError(f"timestamp has no UTC offset: {raw}")
    placed_utc = parsed.astimezone(timezone.utc)
    if order["status"] == "shipped" and start <= placed_utc < end:
        qualifying.append(order)

customers = {}
by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
unknown_regions = set()
for order in qualifying:
    cid = order["customer_id"]
    if cid not in customers:
        customers[cid] = get_json("/customers/" + str(cid))
    customer = customers[cid]
    region = customer["region"]
    if region not in by_region:
        unknown_regions.add(region)
        continue
    amount = Decimal(order["amount_cents"])
    factor = Decimal(100 - customer["discount_pct"]) / Decimal(100)
    discounted = int((amount * factor).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    by_region[region] += discounted

if unknown_regions:
    raise RuntimeError(f"unexpected regions: {sorted(unknown_regions)}")

result = {
    "total_cents": sum(by_region.values()),
    "order_count": len(qualifying),
    "duplicates_skipped": duplicates_skipped,
    "by_region": by_region,
}
print(json.dumps(result, separators=(",", ":")))
print(json.dumps({
    "pages_fetched": pages_fetched,
    "unique_orders_seen": len(orders_by_id),
    "customers_fetched": len(customers),
    "conflicting_duplicate_ids": conflicting_duplicates,
    "request_attempts": request_count,
    "retries": retry_count,
    "token_refreshes": token_refreshes,
}, separators=(",", ":")))
